fn hand(cx: i32, cy: i32, a: i32, len: i32, col: i32) {
    let x: i32 = cx + (len * host::math::cos(a)) / 256;
    let y: i32 = cy + (len * host::math::sin(a)) / 256;
    host::display::draw_line(cx, cy, x, y, col);
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let r: i32 = 110;
    let mut a: i32 = 0;
    while a < 256 {
        let x0: i32 = cx + (r * host::math::cos(a)) / 256;
        let y0: i32 = cy + (r * host::math::sin(a)) / 256;
        let x1: i32 = cx + (r * host::math::cos(a + 4)) / 256;
        let y1: i32 = cy + (r * host::math::sin(a + 4)) / 256;
        host::display::draw_line(x0, y0, x1, y1, 0xcccccc);
        a = a + 4;
    }
    let mut i: i32 = 0;
    while i < 12 {
        let ta: i32 = (i * 256) / 12;
        let x0: i32 = cx + ((r - 10) * host::math::cos(ta)) / 256;
        let y0: i32 = cy + ((r - 10) * host::math::sin(ta)) / 256;
        let x1: i32 = cx + ((r - 2) * host::math::cos(ta)) / 256;
        let y1: i32 = cy + ((r - 2) * host::math::sin(ta)) / 256;
        host::display::draw_line(x0, y0, x1, y1, 0x888888);
        i = i + 1;
    }
    let sec: i32 = (t / 60) % 60;
    let min: i32 = (t / 3600) % 60;
    let hr: i32 = (t / 216000) % 12;
    hand(cx, cy, (sec * 256) / 60 - 64, r - 16, 0xff5555);
    hand(cx, cy, (min * 256) / 60 - 64, r - 26, 0xffffff);
    hand(cx, cy, (hr * 256) / 12 + (min * 256) / 720 - 64, r - 50, 0xffffff);
    host::display::fill_rect(cx - 2, cy - 2, 5, 5, 0xffffff);
    host::display::present();
}
